# ─────────────────────────────────────────────────────────────
#  FUNÇÕES DE DADOS (idênticas ao desktop)
# ─────────────────────────────────────────────────────────────
_brasil_cache = _estados_cache = _linhas_cache = _sub_cache = None

def carregar_brasil():
    global _brasil_cache
    if _brasil_cache is None:
        url = "https://raw.githubusercontent.com/datasets/geo-countries/master/data/countries.geojson"
        mundo = gpd.read_file(url)
        _brasil_cache = mundo[mundo["name"] == "Brazil"]
    return _brasil_cache

def carregar_estados():
    global _estados_cache
    if _estados_cache is None:
        url = "https://raw.githubusercontent.com/codeforamerica/click_that_hood/master/public/data/brazil-states.geojson"
        _estados_cache = gpd.read_file(url)
    return _estados_cache

def carregar_linhas():
    global _linhas_cache
    if _linhas_cache is None:
        kmz_path = "data/raw/[EPE] Linhas de Transmissão.kmz"
        with zipfile.ZipFile(kmz_path, "r") as kmz:
            for a in kmz.namelist():
                if a.endswith(".kml"): kmz.extract(a, "data/raw/era5/")
        gdf = gpd.read_file("data/raw/era5/doc.kml")
        gdf["Tens__o__kV_"] = pd.to_numeric(gdf["Tens__o__kV_"], errors="coerce")
        def extrair_sub(n):
            m = re.search(r"LT \d+ kV (.+?) [-–] (.+?)(?:,|$)", str(n))
            if m: return m.group(1).strip(), m.group(2).strip().split(",")[0].strip()
            return "Desconhecida","Desconhecida"
        gdf[["sub_origem","sub_destino"]] = gdf["Nome"].apply(lambda x: pd.Series(extrair_sub(x)))
        _linhas_cache = gdf
    return _linhas_cache

def carregar_subestacoes():
    global _sub_cache
    if _sub_cache is not None: return _sub_cache
    dados = {
        "NomEmpreend":      ["SE Araraquara 2","SE Tucuruí","SE Belo Monte","SE Estreito","SE Itaubera","SE Xingu","SE Imperatriz"],
        "DscTensaoNominal": ["440 kV","500 kV","800 kV","500 kV","750 kV","800 kV","500 kV"],
        "NomAgente":        ["CPFL","Eletronorte","ANEEL","Eletrobras","Furnas","Norte Energia","Eletronorte"],
        "SigUF":            ["SP","PA","PA","MA","MG","PA","MA"],
        "geometry": [Point(-48.17,-21.78),Point(-49.68,-3.76),Point(-51.62,-3.12),
                     Point(-47.45,-20.48),Point(-47.05,-22.39),Point(-52.0,-3.5),Point(-47.5,-5.5)],
    }
    _sub_cache = gpd.GeoDataFrame(dados, geometry="geometry", crs="EPSG:4326")
    return _sub_cache

def _get_arquivos_inpe():
    r = requests.get(_URL_INPE, verify=False, timeout=15, headers=_HEADERS)
    return sorted(set(re.findall(r'href="(focos_[^"]+\.csv)"', r.text)))

def _get_csv(arquivo):
    r = requests.get(f"{_URL_INPE}{arquivo}", verify=False, timeout=15, headers=_HEADERS)
    if r.status_code == 200 and len(r.text) > 50:
        df = pd.read_csv(StringIO(r.text))
        if {"lat","lon"}.issubset(df.columns): return df
    return None

def carregar_focos_atual():
    try:
        for arquivo in reversed(_get_arquivos_inpe()[-36:]):
            df = _get_csv(arquivo)
            if df is not None and len(df) > 0:
                df["lat_r"] = (df["lat"]/0.01).round()*0.01
                df["lon_r"] = (df["lon"]/0.01).round()*0.01
                df = df.drop_duplicates(subset=["lat_r","lon_r"]).drop(columns=["lat_r","lon_r"]).reset_index(drop=True)
                return df, "10min", arquivo
    except Exception as e:
        print(f"ERRO focos: {e}")
    return pd.DataFrame(), "sem_focos", ""

def carregar_focos_historico():
    """Carrega e concatena os últimos 36 arquivos (~6h) do INPE."""
    try:
        arquivos = _get_arquivos_inpe()[-36:]
        frames = []
        for arquivo in arquivos:
            df = _get_csv(arquivo)
            if df is not None and len(df) > 0:
                df["_arquivo"] = arquivo
                # Deduplicação espacial por arquivo
                df["lat_r"] = (df["lat"]/0.01).round()*0.01
                df["lon_r"] = (df["lon"]/0.01).round()*0.01
                df = df.drop_duplicates(subset=["lat_r","lon_r"]).drop(columns=["lat_r","lon_r"])
                frames.append(df)
        if not frames:
            return pd.DataFrame(), "6h", ""
        df_all = pd.concat(frames, ignore_index=True)
        # Deduplicação global entre arquivos
        df_all["lat_r"] = (df_all["lat"]/0.01).round()*0.01
        df_all["lon_r"] = (df_all["lon"]/0.01).round()*0.01
        df_all = df_all.drop_duplicates(subset=["lat_r","lon_r"]).drop(columns=["lat_r","lon_r"]).reset_index(drop=True)
        return df_all, "6h", f"{len(arquivos)} arquivos"
    except Exception as e:
        print(f"ERRO histórico: {e}")
    return pd.DataFrame(), "6h", ""

