def _build_prev_mobile(tem_modelo):
    if not tem_modelo:
        return html.Div([
            html.Div("⚠️ Modelo não encontrado. Execute o notebook 04_previsao_focos.ipynb ou gere abaixo.",
                     className="m-banner-warn"),
            html.Button("▶  Gerar Previsão", id="m-btn-modelo",
                className="m-btn-primary", n_clicks=0),
            html.Div(id="m-modelo-output"),
        ])

    df_risco = pd.read_parquet(PARQUET_PATH)

    # Selector de horizonte
    horizonte_sel = "Hoje"
    df_h = df_risco[(df_risco["horizonte"]==horizonte_sel) &
                    (df_risco["prob_foco"]>=0.20)].copy()
    df_h["nivel"] = df_h["prob_foco"].apply(
        lambda p: "CRÍTICO" if p>=0.70 else "ALTO" if p>=0.50 else "MÉDIO")

    # Métricas
    n_crit = len(df_h[df_h["prob_foco"]>=0.70])
    n_alto = len(df_h[df_h["prob_foco"]>=0.50])
    n_med  = len(df_h[df_h["prob_foco"]>=0.30])
    pmax   = df_h["prob_foco"].max() if len(df_h)>0 else 0
    dl     = df_h["data_prev"].iloc[0].strftime("%d/%m/%Y") if len(df_h)>0 else "—"

    # Score — intensidade + concentração + decaimento por horizonte
    _decay = {"Hoje": 1.00, "D+1": 0.85, "D+2": 0.70, "D+3": 0.55}
    if len(df_h)>0:
        p      = df_h["prob_foco"].values
        top10m = float(np.sort(p)[::-1][:10].mean())
        fc     = len(df_h[df_h["prob_foco"]>=0.70]) / max(len(df_h),1)
        fa     = len(df_h[df_h["prob_foco"]>=0.50]) / max(len(df_h),1)
        score  = min(100, round((top10m*0.60 + fc*0.25 + fa*0.15)*100 * _decay.get(horizonte_sel,1.0), 1))
    else:
        score = 0.0
    sc = C["red"] if score>=60 else C["orange"] if score>=35 else C["yellow"] if score>=15 else C["green"]

    # Top 5 por estado
    if len(df_h)>0:
        df_h["estado_nm"] = df_h.apply(lambda r: _lat_lon_to_estado(r["lat_grid"],r["lon_grid"]),axis=1)
        df_h["bioma_nm"]  = df_h.apply(lambda r: _lat_lon_to_bioma(r["lat_grid"],r["lon_grid"]),axis=1)
        agg = (df_h.sort_values("prob_foco",ascending=False)
                   .groupby("estado_nm",as_index=False)
                   .agg(prob_max=("prob_foco","max"),n_celulas=("prob_foco","count"),
                        bioma=("bioma_nm","first"))
                   .sort_values("prob_max",ascending=False)
                   .head(5).reset_index(drop=True))
    else:
        agg = pd.DataFrame()

    cor_map = {"CRÍTICO":C["red"],"ALTO":C["orange"],"MÉDIO":C["yellow"]}

    top5_cards = []
    for i, r in agg.iterrows():
        nv  = "CRÍTICO" if r["prob_max"]>=0.70 else "ALTO" if r["prob_max"]>=0.50 else "MÉDIO"
        cor = cor_map.get(nv, C["yellow"])
        top5_cards.append(html.Div([
            html.Div(f"#{i+1} {nv}", className="m-top5-rank", style={"color":cor}),
            html.Div(r["estado_nm"], className="m-top5-estado"),
            html.Div(r["bioma"],     className="m-top5-bioma"),
            html.Div(f"{r['prob_max']:.0%}", className="m-top5-prob", style={"color":cor}),
            html.Div("prob. máx.", className="m-top5-prob-label"),
        ], className="m-top5-card", style={"borderTop":f"2px solid {cor}"}))

    # ── Mapa mobile sem heatmap ──────────────────────────────
    m = folium.Map(location=[-15.0,-53.0], zoom_start=4,
                   tiles="CartoDB dark_matter", control_scale=False)
    if len(df_h) > 0:
        def _prob_cor(p):
            if p >= 0.70: return "#7f1d1d","#ef4444", 9
            if p >= 0.50: return "#7c2d12","#f97316", 7
            if p >= 0.35: return "#713f12","#eab308", 5
            return               "#14532d","#22c55e", 3

        for _, row in df_h[df_h["prob_foco"] >= 0.30].iterrows():
            try:
                p = float(row["prob_foco"])
                border, fill, radius = _prob_cor(p)
                folium.CircleMarker(
                    location=[row["lat_grid"], row["lon_grid"]],
                    radius=radius, color=border,
                    fill=True, fill_color=fill,
                    fill_opacity=0.82, weight=1.2,
                    tooltip=f"{p:.0%}",
                ).add_to(m)
            except: continue

    # ── Ranking por bioma (alternativa visual ao mapa) ────────
    bioma_items = []
    if len(df_h) > 0 and "bioma_nm" in df_h.columns:
        bioma_rank = (df_h.groupby("bioma_nm")["prob_foco"]
                         .agg(["max","count"])
                         .sort_values("max", ascending=False)
                         .reset_index())
        for _, rb in bioma_rank.iterrows():
            pct = rb["max"]
            cor = C["red"] if pct>=0.70 else C["orange"] if pct>=0.50 else C["yellow"] if pct>=0.35 else C["green"]
            bar_w = f"{int(pct*100)}%"
            bioma_items.append(html.Div([
                html.Div([
                    html.Span(rb["bioma_nm"], style={
                        "fontFamily":"Inter,sans-serif","fontSize":"0.8rem",
                        "fontWeight":"600","color":"#cbd5e1","flex":"1",
                    }),
                    html.Span(f"{pct:.0%}", style={
                        "fontFamily":"Manrope,sans-serif","fontSize":"0.9rem",
                        "fontWeight":"800","color":cor,
                    }),
                ], style={"display":"flex","justifyContent":"space-between","marginBottom":"5px"}),
                html.Div(style={
                    "height":"4px","borderRadius":"2px",
                    "background":"#1a2840","position":"relative","overflow":"hidden",
                }),
                html.Div(style={
                    "height":"4px","borderRadius":"2px",
                    "background":f"linear-gradient(90deg,{cor}44,{cor})",
                    "width":bar_w,"position":"relative","marginTop":"-4px",
                    "transition":"width 0.6s ease",
                }),
            ], style={"marginBottom":"12px"}))

    return html.Div([
        # Selector de horizonte
        html.Select(id="m-dd-horizonte",
            children=[html.Option(h,value=h) for h in ["Hoje","D+1","D+2","D+3"]],
            className="m-select"),

        # KPIs
        html.Div([
            m_kpi("Score Global", f"{score:.0f}/100", "ponderado", sc, 0.05),
            m_kpi("Prob. Máxima", f"{pmax:.0%}",      "pico",      C["red"],    0.10),
            m_kpi("Críticos",     str(n_crit),         "≥ 70%",     C["red"],    0.15),
            m_kpi("Altos",        str(n_alto),         "≥ 50%",     C["orange"], 0.20),
        ], className="m-kpi-grid"),

        # Top 5 estados
        m_section("Top 5 Regiões — Detecção Automática"),
        html.Div(top5_cards, className="m-top5-grid") if top5_cards else
            html.Div("Sem regiões acima do limiar.", style={"color":C["muted"],"fontSize":"0.8rem"}),

        # Ranking por bioma
        m_section("Risco por Bioma"),
        html.Div(bioma_items, style={
            "background":C["card"],"border":f"1px solid {C['border']}",
            "borderRadius":"8px","padding":"14px 16px","marginBottom":"20px",
        }) if bioma_items else html.Div(),

        # Mapa pontos
        m_section(f"Mapa — {horizonte_sel} ({dl})"),
        html.Div([
            html.Div("Probabilidade de Foco", style={
                "fontFamily":"JetBrains Mono,monospace","fontSize":"0.55rem",
                "fontWeight":"600","letterSpacing":"0.14em","textTransform":"uppercase",
                "color":C["muted"],"marginBottom":"8px",
            }),
            html.Div([
                html.Div([
                    html.Div(style={"width":f"{sz}px","height":f"{sz}px","borderRadius":"50%",
                        "background":fill,"border":f"1.5px solid {border}","flexShrink":"0"}),
                    html.Div([
                        html.Span(lbl, style={"fontFamily":"Inter,sans-serif","fontSize":"0.72rem",
                            "color":C["text"],"fontWeight":"600"}),
                        html.Span(f" {faixa}", style={"fontFamily":"JetBrains Mono,monospace",
                            "fontSize":"0.62rem","color":C["muted"]}),
                    ]),
                ], style={"display":"flex","alignItems":"center","gap":"8px"})
                for lbl,faixa,fill,border,sz in [
                    ("Crítico","≥ 70%", C["red"],    "#7f1d1d", 12),
                    ("Alto",   "≥ 50%", C["orange"], "#7c2d12",  9),
                    ("Médio",  "≥ 35%", C["yellow"], "#713f12",  7),
                    ("Baixo",  "≥ 30%", C["green"],  "#14532d",  5),
                ]
            ], style={"display":"grid","gridTemplateColumns":"1fr 1fr","gap":"6px"}),
        ], style={"background":C["card"],"border":f"1px solid {C['border']}",
                  "borderRadius":"8px","padding":"10px 14px","marginBottom":"10px"}),
        html.Iframe(srcDoc=m._repr_html_(),
            style={"width":"100%","height":"320px","border":"none","borderRadius":"8px"}),

        html.Div(style={"height":"12px"}),
        html.Button("↺  Regenerar Previsão", id="m-btn-regen",
            className="m-btn-secondary", n_clicks=0),
        html.Div(id="m-regen-output"),
    ], id="m-prev-map-content")


