@callback(
    Output("mobile-content",   "children"),
    Output("m-nav-home",       "className"),
    Output("m-nav-alertas",    "className"),
    Output("m-nav-prev",       "className"),
    Input("m-nav-home",        "n_clicks"),
    Input("m-nav-alertas",     "n_clicks"),
    Input("m-nav-prev",        "n_clicks"),
    prevent_initial_call=False,
)
def navigate(n_home, n_alertas, n_prev):
    ctx   = dash.callback_context
    trig  = ctx.triggered[0]["prop_id"] if ctx.triggered else "m-nav-home.n_clicks"
    base  = "m-nav-btn"
    act   = "m-nav-btn active"
    if "m-nav-alertas" in trig:
        return page_alertas(), base, act, base
    if "m-nav-prev" in trig:
        return page_previsao(), base, base, act
    return page_home(), act, base, base


@callback(
    Output("m-alertas-content","children"),
    Output("m-tab-atual",      "className"),
    Output("m-tab-hist",       "className"),
    Input("m-btn-atualizar",   "n_clicks"),
    Input("m-tab-atual",       "n_clicks"),
    Input("m-tab-hist",        "n_clicks"),
    State("m-dd-estado",       "value"),
    prevent_initial_call=True,
)
def load_alertas(n_btn, n_atual, n_hist, estado):
    ctx  = dash.callback_context
    trig = ctx.triggered[0]["prop_id"] if ctx.triggered else ""
    aba_hist = "m-tab-hist" in trig
    tc_atual = "m-tab" + ("" if aba_hist else " active")
    tc_hist  = "m-tab" + (" active" if aba_hist else "")
    estado   = estado or "Todos"

    try:
        # ── Carrega dados conforme a aba ──
        if aba_hist:
            df, fonte, arq = carregar_focos_historico()
            titulo_ts = f"Últimas 6h · {arq}" if arq else "Últimas 6h"
        else:
            df, fonte, arq = carregar_focos_atual()
            titulo_ts = arq.replace("focos_10min_","").replace(".csv","") if arq else "—"

        if df.empty:
            msg = "Nenhum foco detectado nas últimas 6h." if aba_hist else "Nenhum foco detectado no momento."
            return html.Div(f"✅ {msg}", className="m-banner-ok"), tc_atual, tc_hist

        gdf = processar_focos_mobile(df, estado)
        # Linhas de transmissão só no mapa 10min (performance no mobile)
        m   = fazer_mapa_mobile(gdf, estado, mostrar_linhas=not aba_hist)

        contagem = gdf["risco"].value_counts() if "risco" in gdf.columns else {}
        ts = titulo_ts

        # Tabela top 10
        if "dist_km" in gdf.columns and gdf["dist_km"].notna().any():
            df_top = gdf.sort_values("dist_km").head(10).round(2)
            rows = []
            for _, r in df_top.iterrows():
                nv = r.get("risco","BAIXO") or "BAIXO"
                rows.append(html.Tr([
                    html.Td(f"{r['lat']:.3f}°"),
                    html.Td(f"{r['dist_km']:.1f} km"),
                    html.Td(str(r.get("linha_nome",""))[:25]),
                    html.Td(m_badge(nv)),
                ]))
            table = html.Div([
                html.Div("Top 10 Focos Mais Próximos", className="m-table-head"),
                html.Div(html.Table([
                    html.Thead(html.Tr([html.Th(h) for h in ["Coords","Distância","Linha","Risco"]])),
                    html.Tbody(rows),
                ], className="m-table"),
                style={"overflowX":"auto","maxHeight":"280px","overflowY":"auto"}),
            ], className="m-table-wrap")
        else:
            table = html.Div()

        return html.Div([
            html.Div(ts, style={"fontFamily":"JetBrains Mono,monospace",
                "fontSize":"0.62rem","color":C["dim"],"marginBottom":"12px"}),
            # KPIs
            html.Div([
                m_kpi("Total",    str(len(gdf)),                          "", C["accent"], 0.05),
                m_kpi("Crítico",  str(contagem.get("CRÍTICO",0)), "≤10km", C["red"],    0.10),
                m_kpi("Alto",     str(contagem.get("ALTO",0)),    "≤50km", C["orange"], 0.15),
                m_kpi("Médio",    str(contagem.get("MÉDIO",0)),   "≤100km",C["yellow"], 0.20),
            ], className="m-kpi-grid"),
            # Mapa
            html.Iframe(srcDoc=m._repr_html_(),
                style={"width":"100%","height":"360px","border":"none","borderRadius":"8px","marginBottom":"12px"}),
            table,
        ]), tc_atual, tc_hist

    except Exception as e:
        return html.Div(f"Erro: {e}", className="m-banner-alert"), tc_atual, tc_hist


@callback(
    Output("m-prev-map-content","children"),
    Input("m-dd-horizonte",    "value"),
    prevent_initial_call=False,
)
def update_prev_mobile(horizonte):
    if not os.path.exists(PARQUET_PATH): raise PreventUpdate
    df_risco = pd.read_parquet(PARQUET_PATH)
    horizonte = horizonte or "Hoje"
    df_h = df_risco[(df_risco["horizonte"]==horizonte)&(df_risco["prob_foco"]>=0.20)].copy()
    df_h["nivel"] = df_h["prob_foco"].apply(
        lambda p: "CRÍTICO" if p>=0.70 else "ALTO" if p>=0.50 else "MÉDIO")
    n_crit = len(df_h[df_h["prob_foco"]>=0.70])
    n_alto = len(df_h[df_h["prob_foco"]>=0.50])
    pmax   = df_h["prob_foco"].max() if len(df_h)>0 else 0
    dl     = df_h["data_prev"].iloc[0].strftime("%d/%m/%Y") if len(df_h)>0 else "—"
    _decay = {"Hoje": 1.00, "D+1": 0.85, "D+2": 0.70, "D+3": 0.55}
    if len(df_h)>0:
        p=df_h["prob_foco"].values
        top10m=float(np.sort(p)[::-1][:10].mean())
        fc=len(df_h[df_h["prob_foco"]>=0.70])/max(len(df_h),1)
        fa=len(df_h[df_h["prob_foco"]>=0.50])/max(len(df_h),1)
        score=min(100,round((top10m*0.60+fc*0.25+fa*0.15)*100*_decay.get(horizonte,1.0),1))
        df_h["estado_nm"]=df_h.apply(lambda r:_lat_lon_to_estado(r["lat_grid"],r["lon_grid"]),axis=1)
        df_h["bioma_nm"] =df_h.apply(lambda r:_lat_lon_to_bioma(r["lat_grid"],r["lon_grid"]),axis=1)
        agg=(df_h.sort_values("prob_foco",ascending=False)
                   .groupby("estado_nm",as_index=False)
                   .agg(prob_max=("prob_foco","max"),n_celulas=("prob_foco","count"),bioma=("bioma_nm","first"))
                   .sort_values("prob_max",ascending=False).head(5).reset_index(drop=True))
    else:
        score=0.0; agg=pd.DataFrame()
    sc=C["red"] if score>=60 else C["orange"] if score>=35 else C["yellow"] if score>=15 else C["green"]
    cor_map={"CRÍTICO":C["red"],"ALTO":C["orange"],"MÉDIO":C["yellow"]}

    top5=[]
    for i,r in agg.iterrows():
        nv=("CRÍTICO" if r["prob_max"]>=0.70 else "ALTO" if r["prob_max"]>=0.50 else "MÉDIO")
        cor=cor_map.get(nv,C["yellow"])
        top5.append(html.Div([
            html.Div(f"#{i+1} {nv}",className="m-top5-rank",style={"color":cor}),
            html.Div(r["estado_nm"],className="m-top5-estado"),
            html.Div(r["bioma"],className="m-top5-bioma"),
            html.Div(f"{r['prob_max']:.0%}",className="m-top5-prob",style={"color":cor}),
            html.Div("prob. máx.",className="m-top5-prob-label"),
        ],className="m-top5-card",style={"borderTop":f"2px solid {cor}"}))

    m=folium.Map(location=[-15.0,-53.0],zoom_start=4,tiles="CartoDB dark_matter",control_scale=False)
    if len(df_h)>0:
        def _pc(p):
            if p>=0.70: return "#7f1d1d","#ef4444",9
            if p>=0.50: return "#7c2d12","#f97316",7
            if p>=0.35: return "#713f12","#eab308",5
            return             "#14532d","#22c55e",3
        for _,row in df_h[df_h["prob_foco"]>=0.30].iterrows():
            try:
                p=float(row["prob_foco"]); bd,fl,r=_pc(p)
                folium.CircleMarker(location=[row["lat_grid"],row["lon_grid"]],
                    radius=r,color=bd,fill=True,fill_color=fl,
                    fill_opacity=0.82,weight=1.2,tooltip=f"{p:.0%}").add_to(m)
            except: continue

    return html.Div([
        html.Div([
            m_kpi("Score Global",f"{score:.0f}/100","índice ponderado",sc,0.05),
            m_kpi("Prob. Máxima",f"{pmax:.0%}","célula crítica",C["red"],0.10),
            m_kpi("Críticos",str(n_crit),"prob ≥ 70%",C["red"],0.15),
            m_kpi("Altos",str(n_alto),"prob ≥ 50%",C["orange"],0.20),
        ],className="m-kpi-grid"),
        m_section("Top 5 Regiões — Detecção Automática"),
        html.Div(top5,className="m-top5-grid") if top5 else html.Div("Sem dados.",style={"color":C["muted"],"fontSize":"0.8rem"}),
        m_section(f"Mapa — {horizonte} ({dl})"),
        html.Iframe(srcDoc=m._repr_html_(),style={"width":"100%","height":"340px","border":"none","borderRadius":"8px"}),
        html.Div(style={"height":"12px"}),
        html.Button("↺  Regenerar",id="m-btn-regen",className="m-btn-secondary",n_clicks=0),
        html.Div(id="m-regen-output"),
    ],id="m-prev-map-content")


@callback(
    Output("m-regen-output","children"),
    Input("m-btn-regen","n_clicks"),
    prevent_initial_call=True,
)
def regen_mobile(n):
    if n:
        for p in [PARQUET_PATH, MODELO_PATH]:
            if os.path.exists(p): os.remove(p)
        return html.Div("✅ Modelo removido. Vá ao dashboard desktop para re-treinar.",
            className="m-banner-ok")
    raise PreventUpdate


